class Solution { private int[] temporary;public int[] sortArray(int[] nums){temporary=new int[nums.length];sort(nums,0,nums.length-1);return nums;}private void sort(int[] nums,int left,int right){if(left>=right)return;int middle=left+(right-left)/2;sort(nums,left,middle);sort(nums,middle+1,right);int i=left,j=middle+1,write=left;while(i<=middle||j<=right)temporary[write++]=j>right||i<=middle&&nums[i]<=nums[j]?nums[i++]:nums[j++];for(int index=left;index<=right;index++)nums[index]=temporary[index];} }
